const R = new Map<string, number>(), B = new Map<string, number>();
[...CHARS].forEach((c, i) => { R.set(c, REGULAR[i]); B.set(c, BOLD[i]); });

/** Width of a non-Latin or unknown glyph, per 1000 em. Indic and CJK scripts run wide. */
const UNKNOWN = 650;
const MONO = 600;

/** Width of a string in px at a font size. */
export function textWidth(s: string, size: number, weight: "regular" | "bold" | "mono"): number {
  if (weight === "mono") return [...s].length * MONO * size / 1000;
  const t = weight === "bold" ? B : R;
  let w = 0;
  for (const c of s) w += t.get(c) ?? UNKNOWN;
  return (w * size) / 1000;
}
